var EPOCH *carbon.Carbon

func init() {
	// date of app release
	EPOCH = carbon.Parse("2025-12-30")
}

func GetDailyPrompt() types.Prompt {
	diff := carbon.Now().DiffAbsInDays(EPOCH)
	idx := int(diff) % len(PROMPTS)
	return PROMPTS[idx]
}
